    home_card_buylcai_title: "Buy LCAI Safely",
    home_card_contract_desc: "Paste any token address to instantly see if it's safe, suspicious, or a known scam.",
    home_card_contract_title: "Contract Checker",
    home_card_scams_desc: "Know the most common tactics scammers use to steal from crypto holders.",
    home_card_scams_title: "Common Scams",
    home_card_tips_desc: "Gas fees, slippage, wallet connections, and transaction signing — explained simply.",
    home_card_tips_title: "Tips & Help",
    home_card_url_desc: "Verify a URL before connecting your wallet — one wrong site can drain it in seconds.",
    home_card_url_title: "Website Checker",
    home_card_wallet_desc: "Confirm a destination address is valid before sending crypto you can never get back.",
    home_card_wallet_title: "Wallet Verifier",
    home_intro: "OrcaGuard puts eight safety tools in one place. From checking unknown contracts and phishing URLs, to auditing your own wallet and learning how scams work — everything is explained in plain English, no technical background needed.",
    home_start_html: "<div style=\"display:grid;gap:6px\"><div style=\"font-size:18px;color:var(--text);line-height:1.5\">📋 <strong style=\"color:#fff\">Got a token address?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('contract')\">Contract Checker</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌐 <strong style=\"color:#fff\">Not sure about a website?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('url')\">Website Checker</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🔐 <strong style=\"color:#fff\">Want to see what's in your wallet?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('audit')\">Wallet Audit</span></div><div style=\"font-size:18px;color:var(--text);line-height:1.5\">🌱 <strong style=\"color:#fff\">New to crypto?</strong> &rarr; <span style=\"color:var(--cyan);cursor:pointer\" onclick=\"showPage('scams')\">Common Scams</span></div></div>",
